def __init__(self, conn: sqlite3.Connection, clock=None):
    super().__init__(conn, clock)
    self.customers = CustomerDAO(conn)

def register(self, form: Mapping[str, str]) -> UserAccount:
    username = (form.get('username') or '').strip().lower()
    if not USERNAME.match(username):
        raise ValidationError('Choose a username of 3 to 30 characters: small letters, digits, dot or underscore.')
    password = form.get('password') or ''
    if not 6 <= len(password) <= 72:
        raise ValidationError('The password must have 6 to 72 characters.')
    if password != (form.get('password_again') or ''):
        raise ValidationError('The two passwords are not the same.')
    try:
        customer_type = CustomerType(form.get('customer_type') or '')
    except ValueError:
        raise ValidationError('Please say whether you live in Vietnam or are visiting.') from None
    customer = make_customer(customer_type.value, id=0, user_id=0, full_name='')
    self._fill_customer(customer, form)
    with immediate_transaction(self.conn):
        if self.users.get_by_username(username) is not None:
            raise ValidationError(f'The username {username} is taken. Please choose another one.')
        user = UserAccount(id=0, username=username, password_hash=generate_password_hash(password), display_name=customer.full_name, role=Role.CUSTOMER)
        user.id = self.users.insert(user)
        customer.user_id = user.id
        customer.id = self.customers.insert(customer)
    return user

def get_profile(self, user_id: int) -> Profile:
    user, customer = self._require_customer(user_id)
    return Profile(user=user, customer=customer, addresses=self.customers.list_addresses(customer.id))

def archive_address(self, user_id: int, address_id: int) -> None:
    _, customer = self._require_customer(user_id)
    with immediate_transaction(self.conn):
        if not self.customers.archive_address(address_id, customer.id, self._now()):
            raise NotFoundError('Address not found.')

def _require_customer(self, user_id: int) -> tuple[UserAccount, Customer]:
    user = self._require_user(user_id, Role.CUSTOMER, message='Only customers have a profile here.')
    customer = self.customers.get_by_user_id(user.id)
    if customer is None:
        raise AuthorizationError('Only customers have a profile here.')
    return (user, customer)

@staticmethod
def _fill_customer(customer: Customer, form: Mapping[str, str]) -> None:
    """Validate the fields of the customer's type and copy them onto the customer."""
    full_name = (form.get('full_name') or '').strip()
    if not 2 <= len(full_name) <= 80:
        raise ValidationError('Please enter your full name (2 to 80 characters).')
    phone = re.sub('[\\s.-]', '', form.get('phone') or '')
    customer.full_name = full_name
    if customer.customer_type is CustomerType.LOCAL:
        if not VN_MOBILE.match(phone):
            raise ValidationError('Enter a Vietnamese mobile number of 10 digits, for example 0901234567.')
        customer.phone, customer.email, customer.passport_no, customer.nationality = (phone, None, None, None)
        return
    email = (form.get('email') or '').strip()
    if not EMAIL.match(email) or len(email) > 120:
        raise ValidationError('Enter a valid e-mail address.')
    passport = (form.get('passport_no') or '').replace(' ', '').upper()
    if not PASSPORT.match(passport):
        raise ValidationError('Enter the passport number: 6 to 12 letters or digits.')
    nationality = (form.get('nationality') or '').strip()
    if not 2 <= len(nationality) <= 40:
        raise ValidationError('Please enter your nationality.')
    if phone and (not INTL_PHONE.match(phone)):
        raise ValidationError('The phone number may only contain digits and a leading +.')
    customer.phone, customer.email = (phone or None, email)
    customer.passport_no, customer.nationality = (passport, nationality)

@staticmethod
def _parse_address(form: Mapping[str, str], customer_id: int, address_id: int) -> Address:
    label = (form.get('label') or '').strip()
    if not 1 <= len(label) <= 30:
        raise ValidationError('Give the address a short name, such as Home, Office or Hotel.')
    full_address = (form.get('full_address') or '').strip()
    if not 5 <= len(full_address) <= 200:
        raise ValidationError('Enter the full address (street, number, building or hotel).')
    district = form.get('district') or ''
    if district not in rules.DISTRICTS:
        raise ValidationError('Please choose the district from the list.')
    lat, lon = rules.DISTRICTS[district]
    return Address(id=address_id, customer_id=customer_id, label=label, full_address=full_address, district=district, latitude=lat, longitude=lon)

def authenticate(self, username: str, password: str) -> Optional[UserAccount]:
    """Return the user if the username exists, is active and the password matches."""
    user = self.users.get_by_username((username or '').strip())
    if user is None or not user.is_active:
        return None
    if not check_password_hash(user.password_hash, password or ''):
        return None
    return user

def get_user(self, user_id: int) -> Optional[UserAccount]:
    user = self.users.get_by_id(user_id)
    return user if user and user.is_active else None

def _now(self) -> str:
    """Stored timestamp format: ISO-8601 UTC, seconds."""
    return self.clock().astimezone(timezone.utc).isoformat(timespec='seconds')

def _require_user(self, user_id: int, *roles: Role, message: str='Your account cannot do this.') -> UserAccount:
    user = self.users.get_by_id(user_id) if user_id else None
    if user is None or not user.is_active or user.role not in roles:
        raise AuthorizationError(message)
    return user

def vn_day_start_utc(day: date) -> str:
    """00:00 of a Ho Chi Minh City calendar day, as a stored UTC timestamp (17:00 of the day before)."""
    return datetime.combine(day, time(0, 0), tzinfo=VN_TZ).astimezone(timezone.utc).isoformat(timespec='seconds')

def move_order(orders: OrderDAO, order: Order, to_state: OrderState, now: str, reject_reason: Optional[str]=None) -> None:
    """Check the step on the Order state machine, then write it only if nobody moved the order first."""
    from_state = order.state
    try:
        order.move_to(to_state)
    except InvalidTransition:
        raise ConflictError(f'Order {order.id} is {from_state.value}, so it cannot become {to_state.value}. Nothing was changed.') from None
    if not orders.change_state(order.id, from_state, to_state, now, reject_reason):
        raise ConflictError(f'Order {order.id} was changed by someone else. Nothing was changed; please reload.')

def release_payment(payments: PaymentDAO, order_id: int, now: str) -> Payment:
    """A-06: COD becomes VOIDED, a paid online payment becomes REFUND_PENDING (owed back in full)."""
    payment = payments.get_by_order_id(order_id)
    from_state = payment.state
    try:
        payment.release_for_unfulfilled_order()
    except InvalidTransition:
        raise ConflictError(f'The payment of order {order_id} is {from_state.value}. Nothing was changed.') from None
    if not payments.change_state(order_id, from_state, payment.state, now):
        raise ConflictError(f'The payment of order {order_id} was changed by someone else. Please reload.')
    return payment

@property
def cash_to_collect(self) -> int:
    """COD: the full order total. Online: nothing, the customer has already paid."""
    return self.payment.amount if self.payment.method is PaymentMethod.COD else 0

def board(self, user_id: int) -> ShipperBoard:
    shipper = self._require_shipper(user_id)
    finished = self.deliveries.list_for_shipper(shipper.id, DeliveryState.DELIVERED) + self.deliveries.list_for_shipper(shipper.id, DeliveryState.FAILED)
    finished.sort(key=lambda d: d.finished_at or '', reverse=True)
    return ShipperBoard(waiting=[self._view(d) for d in self.deliveries.list_awaiting_pickup()], mine=[self._view(d) for d in self.deliveries.list_for_shipper(shipper.id, DeliveryState.PICKED_UP)], finished=[self._view(d) for d in finished[:10]])

def get_delivery(self, user_id: int, order_id: int) -> DeliveryView:
    shipper = self._require_shipper(user_id)
    delivery = self._delivery(order_id)
    if delivery.shipper_id not in (None, shipper.id):
        raise AuthorizationError('Another shipper is delivering this order.')
    return self._view(delivery)

def pick_up(self, user_id: int, order_id: int) -> DeliveryView:
    """Atomic: when two shippers press Pick up together, only the first one gets the order."""
    shipper = self._require_shipper(user_id)
    with immediate_transaction(self.conn):
        delivery = self._delivery(order_id)
        if delivery.state is not DeliveryState.AWAITING_PICKUP:
            raise ConflictError(f'Order {order_id} has already been picked up. Nothing was changed.')
        now = self._now()
        if not self.deliveries.take(order_id, shipper.id, now):
            raise ConflictError(f'Order {order_id} has already been picked up. Nothing was changed.')
        move_order(self.orders, self.orders.get_by_id(order_id), OrderState.OUT_FOR_DELIVERY, now)
    return self.get_delivery(user_id, order_id)

def confirm_delivered(self, user_id: int, order_id: int, cash_collected: Optional[str]) -> DeliveryView:
    """COD: the cash entered must equal the order total, and the payment becomes PAID once.
        Online: no cash is taken (the field must be empty or 0)."""
    shipper = self._require_shipper(user_id)
    with immediate_transaction(self.conn):
        delivery = self._own_active_delivery(shipper, order_id)
        payment = self.payments.get_by_order_id(order_id)
        cash = self._parse_cash(cash_collected)
        now = self._now()
        if payment.method is PaymentMethod.COD:
            if cash != payment.amount:
                raise ValidationError(f'Collect exactly {payment.amount:,} VND in cash and enter that amount.')
            payment.move_to(PaymentState.PAID)
            if not self.payments.change_state(order_id, PaymentState.PENDING, PaymentState.PAID, now):
                raise ConflictError('The payment was already recorded. Nothing was changed.')
        else:
            if cash not in (None, 0):
                raise ValidationError('This order was paid online. Do not take cash from the customer.')
            cash = None
        delivery.move_to(DeliveryState.DELIVERED)
        if not self.deliveries.finish(order_id, shipper.id, DeliveryState.DELIVERED, now, cash_collected=cash):
            raise ConflictError('This delivery was already finished. Nothing was changed.')
        move_order(self.orders, self.orders.get_by_id(order_id), OrderState.DELIVERED, now)
    return self.get_delivery(user_id, order_id)

def report_failure(self, user_id: int, order_id: int, reason: str) -> DeliveryView:
    shipper = self._require_shipper(user_id)
    reason = (reason or '').strip()
    if not reason:
        raise ValidationError('Please say why the delivery failed.')
    if len(reason) > 200:
        raise ValidationError('The reason must be at most 200 characters.')
    with immediate_transaction(self.conn):
        delivery = self._own_active_delivery(shipper, order_id)
        now = self._now()
        delivery.move_to(DeliveryState.FAILED)
        if not self.deliveries.finish(order_id, shipper.id, DeliveryState.FAILED, now, failure_reason=reason):
            raise ConflictError('This delivery was already finished. Nothing was changed.')
        move_order(self.orders, self.orders.get_by_id(order_id), OrderState.DELIVERY_FAILED, now)
        release_payment(self.payments, order_id, now)
    return self.get_delivery(user_id, order_id)

def _delivery(self, order_id: int) -> Delivery:
    delivery = self.deliveries.get_by_order_id(order_id)
    if delivery is None:
        raise NotFoundError('There is no delivery for this order. It may not be ready yet.')
    return delivery

def _own_active_delivery(self, shipper: UserAccount, order_id: int) -> Delivery:
    delivery = self._delivery(order_id)
    if delivery.shipper_id != shipper.id:
        raise AuthorizationError('Only the shipper who picked up this order can finish it.')
    if delivery.state is not DeliveryState.PICKED_UP:
        raise ConflictError(f'This delivery is already {delivery.state.value}. Nothing was changed.')
    return delivery

@staticmethod
def _parse_cash(raw: Optional[str]) -> Optional[int]:
    raw = (raw or '').replace(',', '').replace('.', '').strip()
    if raw == '':
        return None
    try:
        value = int(raw)
    except ValueError:
        raise ValidationError('Enter the cash amount as a whole number of VND.') from None
    if value < 0:
        raise ValidationError('The cash amount cannot be negative.')
    return value

def _view(self, delivery: Delivery) -> DeliveryView:
    order = self.orders.get_by_id(delivery.order_id)
    return DeliveryView(delivery=delivery, order=order, payment=self.payments.get_by_order_id(order.id), hub=self.hubs.get_including_archived(order.hub_id), customer=self.customers.get(order.customer_id))

def __init__(self, quote, message: str=CHANGED):
    super().__init__(message)
    self.quote = quote

def __init__(self, message: str, suggestions):
    super().__init__(message)
    self.suggestions = suggestions

def __init__(self, quote, message: str):
    super().__init__(message)
    self.quote = quote

@property
def can_archive(self) -> bool:
    return self.status.hub.archived_at is None and self.open_orders == 0

def __init__(self, conn: sqlite3.Connection, clock=None):
    super().__init__(conn, clock)
    self.hubs = HubDAO(conn)

def get_hub(self, user_id: int, hub_id: int) -> HubAdminView:
    self._require_admin(user_id)
    hub = self.hubs.get_including_archived(hub_id)
    if hub is None:
        raise NotFoundError('Hub not found.')
    return HubAdminView(HubStatus(hub, self.hubs.active_load(hub.id)), self.hubs.open_order_count(hub.id))

def archive_hub(self, user_id: int, hub_id: int) -> Hub:
    """Guard: no open orders (anything not yet delivered, failed, rejected or cancelled).
        Archived hubs leave browsing and checkout; order history still shows them."""
    self._require_admin(user_id)
    with immediate_transaction(self.conn):
        hub = self.hubs.get_including_archived(hub_id)
        if hub is None:
            raise NotFoundError('Hub not found.')
        if hub.archived_at is not None:
            raise ConflictError(f'{hub.name} is already archived.')
        open_orders = self.hubs.open_order_count(hub_id)
        if open_orders:
            raise ConflictError(f'{hub.name} still has {open_orders} open order(s). Archive it when they are finished.')
        self.hubs.archive(hub_id, self._now())
    return self.hubs.get_including_archived(hub_id)

@staticmethod
def _parse(form: Mapping[str, str], hub_id) -> Hub:

    def text(name: str, label: str, max_len: int) -> str:
        value = (form.get(name) or '').strip()
        if not value:
            raise ValidationError(f'Please enter the {label}.')
        if len(value) > max_len:
            raise ValidationError(f'The {label} must be at most {max_len} characters.')
        return value

    def number(name: str, label: str, cast, low, high):
        raw = (form.get(name) or '').strip().replace(',', '')
        try:
            value = cast(raw)
        except ValueError:
            raise ValidationError(f'The {label} must be a number.') from None
        if not low <= value <= high:
            raise ValidationError(f'The {label} must be between {low:,} and {high:,}.')
        return value
    code = text('code', 'hub code', 12).upper()
    if not CODE_PATTERN.match(code):
        raise ValidationError("The hub code looks like HUB-D1: 'HUB-' and 2 to 8 letters or digits.")
    return Hub(id=hub_id, code=code, name=text('name', 'hub name', 80), address_text=text('address_text', 'address', 200), latitude=number('latitude', 'latitude', float, *LAT_RANGE), longitude=number('longitude', 'longitude', float, *LON_RANGE), max_active_orders=number('max_active_orders', 'kitchen capacity', int, 1, MAX_CAPACITY), base_delivery_fee=number('base_delivery_fee', 'base delivery fee', int, 0, MAX_BASE_FEE))

def board(self, user_id: int) -> KitchenBoard:
    staff = self._require_staff(user_id)
    hub = self.hubs.get_including_archived(staff.hub_id)
    columns = {state: [] for state in BOARD_STATES}
    for order in self.orders.list_for_hub(hub.id, BOARD_STATES):
        columns[order.state].append(BoardEntry(order, self.offers.get_open(order.id) is not None))
    return KitchenBoard(hub=hub, columns=columns)

def get_order(self, user_id: int, order_id: int) -> KitchenOrderView:
    staff = self._require_staff(user_id)
    order = self._hub_order(staff, order_id)
    view = KitchenOrderView(order=order, payment=self.payments.get_by_order_id(order.id), open_offer=self.offers.get_open(order.id), offers=self.offers.list_for_order(order.id))
    if order.state is OrderState.PLACED and view.open_offer is None:
        in_order = {l.menu_item_id for l in order.lines}
        menu = [m.item for m in self.hubs.list_menu(order.hub_id) if m.is_available]
        for line in order.lines:
            view.candidates[line.id] = [i for i in menu if i.id not in in_order and i.price <= line.unit_price]
    return view

def offer_replacement(self, user_id: int, order_id: int, order_line_id: int, new_menu_item_id: int) -> ReplacementOffer:
    """One open offer per order, while PLACED; same hub, available, equal or lower price (plan §0.1)."""
    staff = self._require_staff(user_id)
    with immediate_transaction(self.conn):
        order = self._hub_order(staff, order_id)
        if order.state is not OrderState.PLACED:
            raise ConflictError(f'Order {order.id} is {order.state.value}; a replacement can only be offered before the order is confirmed.')
        if self.offers.get_open(order.id) is not None:
            raise ConflictError('This order already has an open replacement offer.')
        line = order.line(order_line_id)
        if line is None:
            raise ValidationError('Choose a dish of this order to replace.')
        item = self.hubs.get_available_item(order.hub_id, new_menu_item_id) if new_menu_item_id else None
        if item is None:
            raise ValidationError('The replacement must be a dish available at this hub.')
        if item.id in {l.menu_item_id for l in order.lines}:
            raise ValidationError(f'{item.name} is already in this order.')
        if item.price > line.unit_price:
            raise ValidationError(f'{item.name} costs more than {line.item_name}. Offer a dish at the same or a lower price.')
        offer = ReplacementOffer(order_id=order.id, order_line_id=line.id, original_item_name=line.item_name, original_unit_price=line.unit_price, new_menu_item_id=item.id, new_item_name=item.name, new_unit_price=item.price, state=OfferState.OFFERED, offered_at=self._now())
        offer.id = self.offers.insert(offer)
    return offer

def list_availability(self, user_id: int) -> tuple[Hub, list[HubMenuItem]]:
    staff = self._require_staff(user_id)
    return (self.hubs.get_including_archived(staff.hub_id), self.hubs.list_menu(staff.hub_id))

def set_availability(self, user_id: int, menu_item_id: int, available: bool) -> None:
    staff = self._require_staff(user_id)
    with immediate_transaction(self.conn):
        if not self.menu.set_available(staff.hub_id, menu_item_id, available):
            raise NotFoundError("This dish is not on your hub's menu.")

def _hub_order(self, staff: UserAccount, order_id: int) -> Order:
    order = self.orders.get_by_id(order_id)
    if order is None:
        raise NotFoundError('Order not found.')
    if order.hub_id != staff.hub_id:
        raise AuthorizationError('This order belongs to another hub.')
    return order

def catalogue(self, user_id: int) -> Catalogue:
    self._require_admin(user_id)
    return Catalogue(brands=self.menu.list_brands(), items=self.menu.list_items())

def rename_brand(self, user_id: int, brand_id: int, name: str) -> Brand:
    self._require_admin(user_id)
    name = self._name(name, 'brand name')
    with immediate_transaction(self.conn):
        self._active_brand(brand_id)
        if self.menu.brand_name_exists(name, except_id=brand_id):
            raise ValidationError(f'A brand called {name} already exists.')
        self.menu.rename_brand(brand_id, name)
    return self.menu.get_brand(brand_id)

def create_item(self, user_id: int, form: Mapping[str, str]) -> MenuItem:
    self._require_admin(user_id)
    item = self._parse_item(form, item_id=None)
    with immediate_transaction(self.conn):
        brand = self._active_brand(item.brand_id)
        if self.menu.item_name_exists(brand.id, item.name):
            raise ValidationError(f'{brand.name} already has a dish called {item.name}.')
        item.id = self.menu.insert_item(item)
    return self.menu.get_item(item.id)

def update_item(self, user_id: int, item_id: int, form: Mapping[str, str]) -> MenuItem:
    """Name, description and price. The brand of a dish does not change."""
    self._require_admin(user_id)
    with immediate_transaction(self.conn):
        current = self._active_item(item_id)
        item = self._parse_item({**form, 'brand_id': str(current.brand_id)}, item_id=item_id)
        if self.menu.item_name_exists(current.brand_id, item.name, except_id=item_id):
            raise ValidationError(f'{current.brand_name} already has a dish called {item.name}.')
        self.menu.update_item(item)
    return self.menu.get_item(item_id)

def archive_item(self, user_id: int, item_id: int) -> MenuItem:
    self._require_admin(user_id)
    with immediate_transaction(self.conn):
        self._active_item(item_id)
        self.menu.archive_item(item_id, self._now())
    return self.menu.get_item(item_id)

def hub_menu(self, user_id: int, hub_id: int) -> HubMenu:
    self._require_admin(user_id)
    hub = self._hub(hub_id)
    listed = self.menu.list_hub_items(hub.id)
    listed_ids = {m.item.id for m in listed}
    active_brands = {b.id for b in self.menu.list_brands() if b.archived_at is None}
    not_listed = [i for i in self.menu.list_items() if i.archived_at is None and i.brand_id in active_brands and (i.id not in listed_ids)]
    return HubMenu(hub=hub, listed=listed, not_listed=not_listed)

def list_item_at_hub(self, user_id: int, hub_id: int, item_id: int) -> None:
    self._require_admin(user_id)
    with immediate_transaction(self.conn):
        hub = self._hub(hub_id)
        if hub.archived_at is not None:
            raise ConflictError(f'{hub.name} is archived.')
        item = self._active_item(item_id)
        if self.menu.get_brand(item.brand_id).archived_at is not None:
            raise ConflictError(f'The brand {item.brand_name} is archived.')
        if self.menu.is_listed(hub_id, item_id):
            raise ConflictError(f'{item.name} is already on the menu of {hub.name}.')
        self.menu.add_listing(hub_id, item_id)

def set_availability(self, user_id: int, hub_id: int, item_id: int, available: bool) -> None:
    self._require_admin(user_id)
    with immediate_transaction(self.conn):
        self._hub(hub_id)
        if not self.menu.set_available(hub_id, item_id, available):
            raise NotFoundError("This dish is not on the hub's menu.")

def _hub(self, hub_id: int) -> Hub:
    hub = self.hubs.get_including_archived(hub_id)
    if hub is None:
        raise NotFoundError('Hub not found.')
    return hub

def _active_brand(self, brand_id) -> Brand:
    brand = self.menu.get_brand(brand_id) if brand_id else None
    if brand is None:
        raise ValidationError('Please choose a brand.')
    if brand.archived_at is not None:
        raise ConflictError(f'The brand {brand.name} is archived.')
    return brand

def _active_item(self, item_id: int) -> MenuItem:
    item = self.menu.get_item(item_id)
    if item is None:
        raise NotFoundError('Dish not found.')
    if item.archived_at is not None:
        raise ConflictError(f'{item.name} is archived and can no longer be changed.')
    return item

@staticmethod
def _name(raw: str, label: str, max_len: int=60) -> str:
    value = (raw or '').strip()
    if not value:
        raise ValidationError(f'Please enter the {label}.')
    if len(value) > max_len:
        raise ValidationError(f'The {label} must be at most {max_len} characters.')
    return value

@classmethod
def _parse_item(cls, form: Mapping[str, str], item_id) -> MenuItem:
    try:
        brand_id = int(form.get('brand_id') or 0)
    except ValueError:
        brand_id = 0
    name = cls._name(form.get('name'), 'dish name')
    description = (form.get('description') or '').strip()
    if len(description) > 200:
        raise ValidationError('The description must be at most 200 characters.')
    raw = (form.get('price') or '').strip().replace(',', '')
    try:
        price = int(raw)
    except ValueError:
        raise ValidationError('The price must be a whole number of VND.') from None
    if not 1 <= price <= MAX_PRICE:
        raise ValidationError(f'The price must be between 1 and {MAX_PRICE:,} VND.')
    return MenuItem(id=item_id, brand_id=brand_id, brand_name='', name=name, description=description, price=price)

