@staticmethod
def _check_payment_choice(customer: Customer, payment: PaymentChoice) -> None:
    if payment.method is PaymentMethod.COD:
        payment.option = None
        return
    if payment.option not in customer.online_options:
        allowed = ', '.join((o.value.replace('_', ' ').lower() for o in customer.online_options))
        raise ValidationError(f'This payment option is not offered to your account. You can pay by {allowed} or cash on delivery.')

def suggest_hubs(self, exclude_hub_id: int, address: Optional[Address]) -> list[HubStatus]:
    """Other active hubs that are not busy and can reach the address, quietest first."""
    options = []
    for status in self.list_hubs():
        if status.hub.id == exclude_hub_id or status.busy:
            continue
        if address is not None and status.hub.distance_to(address) > rules.MAX_DELIVERY_KM:
            continue
        options.append(status)
    options.sort(key=lambda s: (s.load / s.hub.max_active_orders, s.hub.id))
    return options[:rules.MAX_SUGGESTIONS]

def _build_quote(self, customer: Customer, hub_id: int, address_id: Optional[int], quantities: Mapping[int, str], voucher_code: Optional[str]) -> Quote:
    hub = self._require_hub(hub_id)
    lines: list[OrderLine] = []
    for menu_item_id, raw in quantities.items():
        raw = (raw or '').strip()
        if raw == '':
            continue
        item = self.hubs.get_available_item(hub.id, menu_item_id)
        if item is None:
            raise ValidationError(f'Item {menu_item_id} is not available at {hub.name}.')
        try:
            qty = int(raw)
        except ValueError:
            raise ValidationError(f'Quantity for {item.name} must be a whole number.') from None
        if qty <= 0:
            raise ValidationError(f'Quantity for {item.name} must be at least 1.')
        if qty > MAX_QUANTITY:
            raise ValidationError(f'Quantity for {item.name} must be at most {MAX_QUANTITY}.')
        lines.append(OrderLine(menu_item_id=item.id, item_name=item.name, unit_price=item.price, quantity=qty))
    if not lines:
        raise ValidationError('Your cart is empty. Choose at least one item.')
    if not address_id:
        raise ValidationError('Please choose a delivery address.')
    address = self.customers.get_address(address_id, customer.id)
    if address is None:
        raise ValidationError('The selected delivery address is not valid.')
    km = hub.distance_to(address)
    if km > rules.MAX_DELIVERY_KM:
        raise HubUnavailableError(f'{address.label} is {km} km from {hub.name}. We deliver up to {rules.MAX_DELIVERY_KM:g} km.', self.suggest_hubs(hub.id, address))
    load = self.hubs.active_load(hub.id)
    if rules.is_busy(load, hub.max_active_orders):
        raise HubUnavailableError(f'{hub.name} is too busy to take new orders right now.', self.suggest_hubs(hub.id, address))
    quote = Quote(hub=hub, address=address, lines=lines, distance_km=km, delivery_fee=rules.delivery_fee(hub.base_delivery_fee, km))
    quote.quiet_discount = rules.quiet_discount(load, hub.max_active_orders, quote.delivery_fee)
    code = (voucher_code or '').strip()
    if code:
        voucher = self.vouchers.get_by_code(code)
        if voucher is None:
            raise ValidationError(f'Voucher {code} does not exist.')
        problem = voucher.problem(quote.item_subtotal, self._today_vn())
        if problem:
            raise ValidationError(problem)
        quote.voucher, quote.voucher_discount = (voucher, voucher.discount_for(quote.item_subtotal))
    return quote

@property
def net(self) -> int:
    return self.total - self.refunds_owed

def add(self, other: 'SalesRow') -> None:
    for name in ('orders', 'item_sales', 'voucher_discounts', 'delivery_fees', 'total', 'refunds_owed'):
        setattr(self, name, getattr(self, name) + getattr(other, name))

@property
def label(self) -> str:
    if self.status.busy:
        return 'Busy'
    return 'Quiet' if self.status.quiet else 'Normal'

@property
def failure_rate(self) -> Optional[float]:
    finished = self.delivered + self.failed
    return round(100 * self.failed / finished, 1) if finished else None

@property
def avg_wait(self) -> Optional[float]:
    return round(sum(self.waits) / len(self.waits), 1) if self.waits else None

@property
def avg_ride(self) -> Optional[float]:
    return round(sum(self.rides) / len(self.rides), 1) if self.rides else None

def sales_report(self, user_id: int, date_from: Optional[str]=None, date_to: Optional[str]=None, hub_id: Optional[int]=None) -> SalesReport:
    self._require_manager(user_id)
    period, hub = (self._period(date_from, date_to), self._hub(hub_id))
    rows = [SalesRow(label=r['hub_name'], orders=r['orders'], item_sales=r['item_sales'], voucher_discounts=r['voucher_discounts'], delivery_fees=r['delivery_fees'], total=r['total'], refunds_owed=r['refunds_owed']) for r in self.reports.sales_by_hub(period.start_utc, period.end_utc, hub_id)]
    totals = SalesRow(label='All hubs' if hub is None else hub.name)
    for row in rows:
        totals.add(row)
    top = [(r['item_name'], r['quantity'], r['revenue']) for r in self.reports.top_items(period.start_utc, period.end_utc, hub_id)]
    return SalesReport(period=period, hub=hub, rows=rows, totals=totals, top_items=top)

def workload_report(self, user_id: int) -> WorkloadReport:
    self._require_manager(user_id)
    counts: dict[int, dict[OrderState, int]] = {}
    for r in self.reports.open_orders_by_hub_and_state():
        counts.setdefault(r['hub_id'], {})[OrderState(r['state'])] = r['n']
    rows = []
    for hub in self.hubs.list_active():
        per_state = counts.get(hub.id, {})
        load = sum((per_state.get(s, 0) for s in (OrderState.PLACED, OrderState.CONFIRMED, OrderState.PREPARING)))
        rows.append(WorkloadRow(status=HubStatus(hub, load), counts=per_state))
    return WorkloadReport(as_of=self._now(), rows=rows)

def delivery_report(self, user_id: int, date_from: Optional[str]=None, date_to: Optional[str]=None, hub_id: Optional[int]=None) -> DeliveryReport:
    self._require_manager(user_id)
    period, hub = (self._period(date_from, date_to), self._hub(hub_id))
    by_hub: dict[int, DeliveryRow] = {}
    by_shipper: dict[int, DeliveryRow] = {}
    overall = DeliveryRow(label='All deliveries')
    for r in self.reports.finished_deliveries(period.start_utc, period.end_utc, hub_id):
        targets = (by_hub.setdefault(r['hub_id'], DeliveryRow(label=r['hub_name'])), by_shipper.setdefault(r['shipper_id'], DeliveryRow(label=r['shipper_name'] or 'Unknown')), overall)
        wait = _minutes(r['ready_at'], r['picked_up_at'])
        ride = _minutes(r['picked_up_at'], r['finished_at']) if r['state'] == 'DELIVERED' else None
        for row in targets:
            if r['state'] == 'DELIVERED':
                row.delivered += 1
            else:
                row.failed += 1
            if wait is not None:
                row.waits.append(wait)
            if ride is not None:
                row.rides.append(ride)
    return DeliveryReport(period=period, hub=hub, by_hub=list(by_hub.values()), by_shipper=sorted(by_shipper.values(), key=lambda r: r.label), overall=overall)

def _hub(self, hub_id: Optional[int]) -> Optional[Hub]:
    if not hub_id:
        return None
    hub = self.hubs.get_including_archived(hub_id)
    if hub is None:
        raise ValidationError('Choose a hub from the list.')
    return hub

def _period(self, date_from: Optional[str], date_to: Optional[str]) -> Period:
    today = date.fromisoformat(self._today_vn())
    try:
        end = date.fromisoformat(date_to) if date_to else today
        start = date.fromisoformat(date_from) if date_from else end - timedelta(days=DEFAULT_DAYS - 1)
    except ValueError:
        raise ValidationError('Enter the dates as YYYY-MM-DD.') from None
    if start > end:
        raise ValidationError('The first day must be on or before the last day.')
    if (end - start).days >= MAX_DAYS:
        raise ValidationError(f'Choose a period of at most {MAX_DAYS} days.')
    return Period(date_from=start.isoformat(), date_to=end.isoformat(), start_utc=vn_day_start_utc(start), end_utc=vn_day_start_utc(end + timedelta(days=1)))

def _minutes(start: Optional[str], end: Optional[str]) -> Optional[float]:
    if not start or not end:
        return None
    return (datetime.fromisoformat(end) - datetime.fromisoformat(start)).total_seconds() / 60

