def create_staff(self, user_id: int, form: Mapping[str, str]) -> UserAccount:
    self._require_admin(user_id)
    username = (form.get('username') or '').strip().lower()
    if not USERNAME.match(username):
        raise ValidationError('The username has 3 to 30 small letters, digits, dots or underscores.')
    try:
        role = Role(form.get('role') or '')
    except ValueError:
        role = None
    if role not in STAFF_ROLES:
        raise ValidationError('Choose kitchen staff, shipper, admin or manager. Customers register themselves.')
    display_name = self._display_name(form)
    password = self._password(form, required=True)
    with immediate_transaction(self.conn):
        if self.users.get_by_username(username) is not None:
            raise ValidationError(f'The username {username} is taken.')
        user = UserAccount(id=0, username=username, password_hash=generate_password_hash(password), display_name=display_name, role=role, hub_id=self._hub_for(role, form.get('hub_id')))
        user.id = self.users.insert(user)
    return user

def set_active(self, user_id: int, target_id: int, active: bool) -> UserAccount:
    admin = self._require_admin(user_id)
    if target_id == admin.id:
        raise ConflictError('You cannot deactivate your own account.')
    with immediate_transaction(self.conn):
        user = self._target(target_id)
        if not self.users.set_active(target_id, active):
            raise ConflictError(f"{user.username} is already {('active' if active else 'deactivated')}.")
    return self._target(target_id)

def _target(self, target_id: int) -> UserAccount:
    user = self.users.get_by_id(target_id)
    if user is None:
        raise NotFoundError('User not found.')
    return user

def _hub_for(self, role: Role, raw_hub_id) -> Optional[int]:
    if role is not Role.KITCHEN_STAFF:
        return None
    try:
        hub = self.hubs.get(int(raw_hub_id or 0))
    except ValueError:
        hub = None
    if hub is None:
        raise ValidationError('Kitchen staff need an active hub to work in.')
    return hub.id

@staticmethod
def _display_name(form: Mapping[str, str]) -> str:
    name = (form.get('display_name') or '').strip()
    if not 2 <= len(name) <= 60:
        raise ValidationError('Enter a display name of 2 to 60 characters.')
    return name

@staticmethod
def _password(form: Mapping[str, str], required: bool) -> str:
    password = form.get('password') or ''
    if not password and (not required):
        return ''
    if not 6 <= len(password) <= 72:
        raise ValidationError('The password must have 6 to 72 characters.')
    return password

def __init__(self, conn: sqlite3.Connection, clock=None):
    super().__init__(conn, clock)
    self.vouchers = VoucherDAO(conn)

def list_vouchers(self, user_id: int) -> list[Voucher]:
    self._require_admin(user_id)
    return self.vouchers.list_all()

def get_voucher(self, user_id: int, voucher_id: int) -> Voucher:
    self._require_admin(user_id)
    voucher = self.vouchers.get(voucher_id)
    if voucher is None:
        raise NotFoundError('Voucher not found.')
    return voucher

def update_voucher(self, user_id: int, voucher_id: int, form: Mapping[str, str]) -> Voucher:
    self._require_admin(user_id)
    voucher = self._parse(form, voucher_id=voucher_id)
    with immediate_transaction(self.conn):
        current = self.vouchers.get(voucher_id)
        if current is None:
            raise NotFoundError('Voucher not found.')
        if current.archived_at is not None:
            raise ConflictError(f'{current.code} is archived and can no longer be changed.')
        if self.vouchers.code_exists(voucher.code, except_id=voucher_id):
            raise ValidationError(f'The code {voucher.code} already exists.')
        self.vouchers.update(voucher)
    return voucher

def archive_voucher(self, user_id: int, voucher_id: int) -> Voucher:
    self._require_admin(user_id)
    with immediate_transaction(self.conn):
        current = self.vouchers.get(voucher_id)
        if current is None:
            raise NotFoundError('Voucher not found.')
        if not self.vouchers.archive(voucher_id, self._now()):
            raise ConflictError(f'{current.code} is already archived.')
    return self.vouchers.get(voucher_id)

@staticmethod
def _parse(form: Mapping[str, str], voucher_id) -> Voucher:
    code = (form.get('code') or '').strip().upper()
    if not CODE.match(code):
        raise ValidationError('The code has 3 to 20 capital letters or digits, for example LUNCH10.')
    description = (form.get('description') or '').strip()
    if len(description) > 120:
        raise ValidationError('The description must be at most 120 characters.')
    try:
        discount_type = DiscountType(form.get('discount_type') or '')
    except ValueError:
        raise ValidationError('Choose a fixed amount or a percentage.') from None

    def whole(name: str, label: str, required: bool=True):
        raw = (form.get(name) or '').strip().replace(',', '')
        if raw == '' and (not required):
            return None
        try:
            value = int(raw)
        except ValueError:
            raise ValidationError(f'The {label} must be a whole number.') from None
        if value < 0:
            raise ValidationError(f'The {label} cannot be negative.')
        return value
    value = whole('discount_value', 'discount')
    if value == 0 or (discount_type is DiscountType.PERCENT and value > 100):
        raise ValidationError('A percentage discount is between 1 and 100; a fixed discount is above 0.')
    min_subtotal = whole('min_subtotal', 'minimum order', required=False) or 0
    max_discount = whole('max_discount', 'maximum discount', required=False)
    if max_discount == 0:
        max_discount = None
    try:
        valid_from = date.fromisoformat(form.get('valid_from') or '').isoformat()
        valid_until = date.fromisoformat(form.get('valid_until') or '').isoformat()
    except ValueError:
        raise ValidationError('Enter both dates as YYYY-MM-DD.') from None
    if valid_from > valid_until:
        raise ValidationError('The voucher must start on or before its last day.')
    return Voucher(id=voucher_id, code=code, description=description, discount_type=discount_type, discount_value=value, min_subtotal=min_subtotal, max_discount=max_discount, valid_from=valid_from, valid_until=valid_until)

@property
def online_options(self) -> tuple[OnlineOption, ...]:
    return rules.ONLINE_OPTIONS[self.customer_type]

@property
def busy(self) -> bool:
    return rules.is_busy(self.load, self.hub.max_active_orders)

@property
def quiet(self) -> bool:
    return rules.is_quiet(self.load, self.hub.max_active_orders)

@property
def load_percent(self) -> int:
    return round(100 * self.load / self.hub.max_active_orders)

def problem(self, item_subtotal: int, today: str) -> Optional[str]:
    """Why this voucher cannot be used on an order today, or None."""
    if self.archived_at is not None:
        return f'Voucher {self.code} is no longer offered.'
    if not self.valid_from <= today <= self.valid_until:
        return f'Voucher {self.code} is not valid today.'
    if item_subtotal < self.min_subtotal:
        return f'Voucher {self.code} needs dishes worth at least {self.min_subtotal:,} VND.'
    return None

def discount_for(self, item_subtotal: int) -> int:
    if self.discount_type is DiscountType.PERCENT:
        amount = item_subtotal * self.discount_value // 100
    else:
        amount = self.discount_value
    if self.max_discount is not None:
        amount = min(amount, self.max_discount)
    return min(amount, item_subtotal)

@property
def line_total(self) -> int:
    return self.unit_price * self.quantity

@property
def item_subtotal(self) -> int:
    return sum((line.line_total for line in self.lines))

@property
def total(self) -> int:
    return self.item_subtotal - self.voucher_discount + self.delivery_fee - self.quiet_discount

def move_to(self, new_state: PaymentState) -> None:
    _check_move(PAYMENT_TRANSITIONS, self.state, new_state, f'Payment of order {self.order_id}')
    self.state = new_state

def release_for_unfulfilled_order(self) -> None:
    """Rejection, cancellation or failed delivery (A-06): COD is voided, an online payment is owed back."""
    self.move_to(PaymentState.VOIDED if self.method is PaymentMethod.COD else PaymentState.REFUND_PENDING)

@property
def item_subtotal(self) -> int:
    return sum((line.line_total for line in self.lines))

@property
def total(self) -> int:
    return self.item_subtotal - self.voucher_discount + self.delivery_fee - self.quiet_discount

@property
def is_closed(self) -> bool:
    return self.state in rules.TERMINAL_ORDER_STATES

@classmethod
def place(cls, customer_id: int, quote: Quote, idempotency_token: str, placed_at: str) -> 'Order':
    """Create a new order in state PLACED from an accepted quote."""
    return cls(customer_id=customer_id, hub_id=quote.hub.id, address_id=quote.address.id, state=OrderState.PLACED, delivery_fee=quote.delivery_fee, idempotency_token=idempotency_token, placed_at=placed_at, delivery_address_text=quote.address.full_address, distance_km=quote.distance_km, voucher_id=quote.voucher.id if quote.voucher else None, voucher_discount=quote.voucher_discount, quiet_discount=quote.quiet_discount, lines=[OrderLine(l.menu_item_id, l.item_name, l.unit_price, l.quantity) for l in quote.lines])

def move_to(self, new_state: OrderState) -> None:
    if not self.can_move_to(new_state):
        raise InvalidTransition(f'Order {self.id}: {self.state.value} -> {new_state.value} is not allowed')
    self.state = new_state

def move_to(self, new_state: DeliveryState) -> None:
    _check_move(DELIVERY_TRANSITIONS, self.state, new_state, f'Delivery of order {self.order_id}')
    self.state = new_state

def move_to(self, new_state: OfferState) -> None:
    _check_move(OFFER_TRANSITIONS, self.state, new_state, f'Replacement offer {self.id}')
    self.state = new_state

def _check_move(table: dict, current, new, what: str) -> None:
    if new not in table[current]:
        raise InvalidTransition(f'{what}: {current.value} -> {new.value} is not allowed')

def make_customer(customer_type: str, **fields) -> Customer:
