def save_lines_and_totals(self, order: Order) -> None:
    """Persist an accepted replacement: the changed lines and the recomputed totals."""
    for line in order.lines:
        self.conn.execute('UPDATE order_line SET menu_item_id = ?, item_name = ?, unit_price = ? WHERE id = ? AND order_id = ?', (line.menu_item_id, line.item_name, line.unit_price, line.id, order.id))
    self.conn.execute('UPDATE orders SET item_subtotal = ?, voucher_discount = ?, total_amount = ? WHERE id = ?', (order.item_subtotal, order.voucher_discount, order.total, order.id))

