def _load(self, row: Optional[sqlite3.Row]) -> Optional[Order]:
    if row is None:
        return None
    line_rows = self.conn.execute('SELECT id, menu_item_id, item_name, unit_price, quantity FROM order_line WHERE order_id = ? ORDER BY id', (row['id'],)).fetchall()
    fields = dict(row)
    fields['state'] = OrderState(fields['state'])
    return Order(**fields, lines=[OrderLine(**dict(r)) for r in line_rows])

