    if r is None:
        return None
    return Payment(id=r['id'], order_id=r['order_id'], method=PaymentMethod(r['method']), state=PaymentState(r['state']), amount=r['amount'], created_at=r['created_at'], updated_at=r['updated_at'], refund_amount=r['refund_amount'], provider_ref=r['provider_ref'], online_option=OnlineOption(r['online_option']) if r['online_option'] else None)

