def authorise(self, amount: int, option: OnlineOption, outcome: str) -> Authorisation:
    if outcome == APPROVE:
        ref = f'SIM-{uuid.uuid4().hex[:12].upper()}'
        log.info('payment simulator: authorised %s VND by %s, ref %s', amount, option.value, ref)
        return Authorisation(True, ref, 'Approved')
    log.info('payment simulator: declined %s VND by %s (FAILED, no order created)', amount, option.value)
    return Authorisation(False, None, 'The payment was declined.')

def sales_by_hub(self, start_utc: str, end_utc: str, hub_id: Optional[int]) -> list[sqlite3.Row]:
    """DELIVERED orders whose delivery finished in [start_utc, end_utc), one row per hub."""
    return self.conn.execute("SELECT h.id AS hub_id, h.name AS hub_name, COUNT(*) AS orders,        SUM(o.item_subtotal) AS item_sales, SUM(o.voucher_discount) AS voucher_discounts,        SUM(o.delivery_fee - o.quiet_discount) AS delivery_fees, SUM(o.total_amount) AS total,        SUM(p.refund_amount) AS refunds_owed FROM orders o JOIN delivery d ON d.order_id = o.id JOIN payment p ON p.order_id = o.id JOIN hub h ON h.id = o.hub_id WHERE o.state = 'DELIVERED' AND d.finished_at >= ? AND d.finished_at < ?   AND (? IS NULL OR o.hub_id = ?) GROUP BY h.id, h.name ORDER BY h.id", (start_utc, end_utc, hub_id, hub_id)).fetchall()

def top_items(self, start_utc: str, end_utc: str, hub_id: Optional[int], limit: int=10) -> list[sqlite3.Row]:
    """Dishes sold on DELIVERED orders in the period, by revenue (line level, so the join is correct here)."""
    return self.conn.execute("SELECT ol.item_name, SUM(ol.quantity) AS quantity, SUM(ol.unit_price * ol.quantity) AS revenue FROM order_line ol JOIN orders o ON o.id = ol.order_id JOIN delivery d ON d.order_id = o.id WHERE o.state = 'DELIVERED' AND d.finished_at >= ? AND d.finished_at < ?   AND (? IS NULL OR o.hub_id = ?) GROUP BY ol.item_name ORDER BY revenue DESC, ol.item_name LIMIT ?", (start_utc, end_utc, hub_id, hub_id, limit)).fetchall()

def open_orders_by_hub_and_state(self) -> list[sqlite3.Row]:
