    return self.conn.execute("SELECT hub_id, state, COUNT(*) AS n FROM orders WHERE state IN ('PLACED', 'CONFIRMED', 'PREPARING', 'READY', 'OUT_FOR_DELIVERY') GROUP BY hub_id, state").fetchall()

def finished_deliveries(self, start_utc: str, end_utc: str, hub_id: Optional[int]) -> list[sqlite3.Row]:
    """Deliveries that ended (DELIVERED or FAILED) in [start_utc, end_utc)."""
    return self.conn.execute("SELECT o.id AS order_id, o.hub_id, h.name AS hub_name, d.state, d.ready_at, d.picked_up_at,        d.finished_at, d.shipper_id, u.display_name AS shipper_name FROM delivery d JOIN orders o ON o.id = d.order_id JOIN hub h ON h.id = o.hub_id LEFT JOIN user_account u ON u.id = d.shipper_id WHERE d.state IN ('DELIVERED', 'FAILED') AND d.finished_at >= ? AND d.finished_at < ?   AND (? IS NULL OR o.hub_id = ?) ORDER BY o.hub_id, d.finished_at", (start_utc, end_utc, hub_id, hub_id)).fetchall()

