        view = _controller().select_hub(uid(), hub_id)
    except ValidationError as exc:
        return _render_hubs(str(exc), status=400)
    groups: dict[str, list] = {}
    for entry in view.menu:
        groups.setdefault(entry.item.brand_name, []).append(entry)
    return (render_template('order/menu.html', view=view, groups=groups.items(), error=error, quantities=quantities, selected_address_id=address_id, voucher_code=voucher_code or ''), status)

